import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"سب کے لیے راستے کی ضمانت کا نظام","description":"","frontmatter":{},"headers":[],"relativePath":"ur/08-人人有路保障体系.md","filePath":"ur/08-人人有路保障体系.md"}'),d={name:"ur/08-人人有路保障体系.md"};function l(i,t,h,n,s,u){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="سب-کے-لیے-راستے-کی-ضمانت-کا-نظام" tabindex="-1">سب کے لیے راستے کی ضمانت کا نظام <a class="header-anchor" href="#سب-کے-لیے-راستے-کی-ضمانت-کا-نظام" aria-label="Permalink to &quot;سب کے لیے راستے کی ضمانت کا نظام&quot;">​</a></h1><table tabindex="0"><thead><tr><th>پروجیکٹ</th><th>مواد</th></tr></thead><tbody><tr><td>دستاویز نمبر</td><td>08</td></tr><tr><td>ماڈیول</td><td>عمومی اصول اور بنیادی ترتیبات</td></tr><tr><td>کلیدی الفاظ</td><td>سب کے لیے راستہ، ضمانت کا نظام، ارتقاء کی بنیادی لکیر، کمزور گروہ، آفاقی</td></tr></tbody></table><h2 id="اولًا-سب-کے-لیے-راستے-کی-بنیادی-تعریف" tabindex="-1">اولًا. سب کے لیے راستے کی بنیادی تعریف <a class="header-anchor" href="#اولًا-سب-کے-لیے-راستے-کی-بنیادی-تعریف" aria-label="Permalink to &quot;اولًا. سب کے لیے راستے کی بنیادی تعریف&quot;">​</a></h2><p>سب کے لیے راستہ لنگر سمبیوٹک تہذیب کے بنیادی سماجی اہداف میں سے ایک ہے، جس کا مطلب ہے کہ ہینگ یوانژو میں ہر زندگی، اس کی نسل، نسب، صلاحیت، سطح، یا دولت کی صورت حال سے قطع نظر، اپنے لیے موزوں ایک ارتقاء کا راستہ حاصل کر سکتی ہے، اور اپنی محنت کے ذریعے سطح کی بلندی اور زندگی کی کمال کے موقع حاصل کر سکتی ہے۔ &quot;راستہ ہونا&quot; صرف سادھائی کے طریقے سیکھنے کے لیے نہیں ہے، بلکہ استعمال کے لیے وسائل، پوچھنے کے لیے اساتذہ، سادھائی کے لیے ماحول، اور انحصار کے لیے اداروں کے لیے بھی ہے۔</p><p>سب کے لیے راستہ اور زیادہ محنت زیادہ انعام سمبیوٹک تہذیب کے تقسیمی نظام کے دو ستون ہیں۔ زیادہ محنت زیادہ انعام جو مسئلہ حل کرتا ہے وہ &quot;کارکردگی&quot; کا مسئلہ ہے، اور طاقتوروں کو مزید قدر تخلیق کرنے کی ترغیب دیتا ہے؛ سب کے لیے راستہ جو مسئلہ حل کرتا ہے وہ &quot;انصاف&quot; کا مسئلہ ہے، اور اس بات کو یقینی بناتا ہے کہ کمزوروں کو ارتقاء کے نظام نے ترک نہ کیا ہے۔ دونوں ایک دوسرے کی تکمیل کرتے ہیں، اور ایک دوسرے کے بغیر کوئی بھی مکمل نہیں ہے۔ سب کے لیے راستے کے بغیر، زیادہ محنت زیادہ انعام طاقتوروں کے کمزوروں کو کھا جانے میں بدل جائے گا؛ زیادہ محنت زیادہ انعام کے بغیر، سب کے لیے راستہ یکساںیت میں بدل جائے گا۔</p><h2 id="ثانیًا-سب-کے-لیے-راستے-کی-ضرورت" tabindex="-1">ثانیًا. سب کے لیے راستے کی ضرورت <a class="header-anchor" href="#ثانیًا-سب-کے-لیے-راستے-کی-ضرورت" aria-label="Permalink to &quot;ثانیًا. سب کے لیے راستے کی ضرورت&quot;">​</a></h2><p>سب کے لیے راستے کی ضمانت کے نظام کا قیام، درج ذیل گہری سمجھ پر مبنی ہے:</p><h3 id="_2-1-ارتقاء-کا-حق-سب-سے-بنیادی-زندگی-کا-حق-ہے" tabindex="-1">2.1 ارتقاء کا حق سب سے بنیادی زندگی کا حق ہے <a class="header-anchor" href="#_2-1-ارتقاء-کا-حق-سب-سے-بنیادی-زندگی-کا-حق-ہے" aria-label="Permalink to &quot;2.1 ارتقاء کا حق سب سے بنیادی زندگی کا حق ہے&quot;">​</a></h3><p>سادھائی کی تہذیب میں، ارتقاء کا حق صرف ترقی کا حق نہیں ہے، بلکہ بقا کا حق بھی ہے۔ کم سطح کی زندگی، جب کائنات میں مختلف خطرات (جیسے جہت کے اتار چڑھاو، توانائی کے طوفان، غیر ملکی نسلوں کے حملے وغیرہ) کا سامنا کرتی ہے، تو اس کی بقا کا امکان اعلیٰ سطح کی زندگی سے کہیں کم ہوتا ہے۔ لہذا، اس بات کو یقینی بنانا کہ ہر زندگی کے پاس ارتقاء کا راستہ ہے، بنیادی طور پر یہ یقینی بنانا ہے کہ ہر زندگی کا بنیادی بقا کا حق محفوظ ہے۔</p><h3 id="_2-2-ابتدائی-صلاحیت-کا-فرق-ارتقاء-کی-قسمت-کا-تعین-نہیں-کرنا-چاہیے" tabindex="-1">2.2 ابتدائی صلاحیت کا فرق ارتقاء کی قسمت کا تعین نہیں کرنا چاہیے <a class="header-anchor" href="#_2-2-ابتدائی-صلاحیت-کا-فرق-ارتقاء-کی-قسمت-کا-تعین-نہیں-کرنا-چاہیے" aria-label="Permalink to &quot;2.2 ابتدائی صلاحیت کا فرق ارتقاء کی قسمت کا تعین نہیں کرنا چاہیے&quot;">​</a></h3><p>ہر زندگی کی ابتدائی صلاحیت (نسلی صلاحیت، خاندانی پس منظر، پیدائش کا جہت، پیدائشی قابلیت وغیرہ) میں بہت بڑا فرق ہے۔ لوٹ مار ازم کے دور میں، یہ فرق اکثر ناقابل عبور خندق میں بڑھا دیا جاتا تھا — اچھے خاندان کی زندگی معیاری وسائل پر اجارہ داری کرتی تھی، جبکہ خراب خاندان کی زندگی یہاں تک کہ بنیادی سادھائی کے طریقے بھی حاصل نہیں کر سکتی تھی۔ سمبیوٹک تہذیب کا ماننا ہے کہ ابتدائی صلاحیت کا فرق معروضی طور پر موجود ہے، لیکن یہ ارتقاء کی قسمت کا تعین کرنے والا واحد عنصر نہیں ہونا چاہیے۔ ادارے کا کام ہے کہ وہ اس ابتدائی فرق کی تلافی کرے، اور ہر زندگی کو بعد کی محنت کے ذریعے قسمت بدلنے کا موقع دے۔</p><h3 id="_2-3-ترک-کردہ-افراد-تہذیب-کے-لیے-ممکنہ-نقصان-ہیں" tabindex="-1">2.3 ترک کردہ افراد تہذیب کے لیے ممکنہ نقصان ہیں <a class="header-anchor" href="#_2-3-ترک-کردہ-افراد-تہذیب-کے-لیے-ممکنہ-نقصان-ہیں" aria-label="Permalink to &quot;2.3 ترک کردہ افراد تہذیب کے لیے ممکنہ نقصان ہیں&quot;">​</a></h3><p>ہر زندگی میں ارتقاء کی صلاحیت ہے، اور اکثر صرف موزوں راستے اور وسائل کی کمی ہے۔ ایک ایسی زندگی جو نچلی سطح میں جدوجہد کر رہی ہے، موزوں سادھائی کے نظام حاصل کرنے کے بعد حیرت انگیز صلاحیت کا مظاہرہ کر سکتی ہے؛ ایک ایسا فرد جسے &quot;بیکار&quot; سمجھا جاتا ہے، ہو سکتا ہے اس نے صرف اپنے لیے موزوں ارتقاء کی سمت نہیں پائی ہے۔ سب کے لیے راستے کی ضمانت کے نظام کا مطلب یہ ہے کہ کسی بھی ممکنہ ارتقاء کار کو ترک نہ کریں، اور تہذیب کے انسانی وسائل کو جتنا ممکن ہو وسعت دیں۔</p><h3 id="_2-4-آفاقی-ارتقاء-کائنات-کی-جہتی-عروج-کی-بنیاد-ہے" tabindex="-1">2.4 آفاقی ارتقاء کائنات کی جہتی عروج کی بنیاد ہے <a class="header-anchor" href="#_2-4-آفاقی-ارتقاء-کائنات-کی-جہتی-عروج-کی-بنیاد-ہے" aria-label="Permalink to &quot;2.4 آفاقی ارتقاء کائنات کی جہتی عروج کی بنیاد ہے&quot;">​</a></h3><p>کائنات کی مجموعی جہتی عروج صرف چند انتہائی طاقتور افراد پر منحصر نہیں ہے، بلکہ دس ہزار نسلوں کے عام لوگوں کی آفاقی ارتقاء کی ضرورت ہے۔ لنگر پوائنٹ جال کی کارکردگی جال سے منسلک زندگیوں کی تعداد اور معیار کے ساتھ مثبت طور پر منسلک ہے۔ جب زیادہ سے زیادہ زندگی سادھائی کے نظام سے منسلک ہوتی ہے اور اپنی سطح بڑھاتی ہے، تو پوری لنگر پوائنٹ جال کے توانائی کے چکر اور قانون کے چلانے میں مزید استحکام اور کارکردگی آتی ہے، اور کائنات کی جہتی عروج کی عمل بھی تیز ہوتی ہے۔</p><h2 id="ثالثًا-ضمانت-کے-نظام-کا-درجہ-بندی-کا-ڈھانچہ" tabindex="-1">ثالثًا. ضمانت کے نظام کا درجہ بندی کا ڈھانچہ <a class="header-anchor" href="#ثالثًا-ضمانت-کے-نظام-کا-درجہ-بندی-کا-ڈھانچہ" aria-label="Permalink to &quot;ثالثًا. ضمانت کے نظام کا درجہ بندی کا ڈھانچہ&quot;">​</a></h2><p>سب کے لیے راستے کی ضمانت کا نظام چار درجوں میں تقسیم ہے، جو بنیادی سے اعلیٰ درجے تک ایک مکمل ضمانت کا سلسلہ بناتا ہے:</p><table tabindex="0"><thead><tr><th>درجہ</th><th>نام</th><th>ضمانت کا مواد</th><th>احاطہ کرنے کا دائرہ</th></tr></thead><tbody><tr><td>پہلا درجہ</td><td>بنیادی ضمانت</td><td>مفت سادھائی کے طریقے، کم از کم وسائل کی تقسیم، بنیادی طبی اور تعلیمی خدمات</td><td>تمام زندگی، کوئی داخلے کی رکاوٹ نہیں</td></tr><tr><td>دوسرا درجہ</td><td>ہدایت شدہ مدد</td><td>کمزور گروہوں کے لیے اضافی وسائل، اساتذہ، ٹیکنالوجی کی مدد</td><td>کم ابتدائی صلاحیت والے افراد اور نسلیں</td></tr><tr><td>تیسرا درجہ</td><td>مواقع کی توسیع</td><td>اعلیٰ درجے کی سادھائی کے مواقع، جہت کی تبادلہ، خصوصی منصوبوں میں شرکت کا حق</td><td>صلاحیت رکھنے والے لیکن وسائل کی کمی والے سادھک</td></tr><tr><td>چوتھا درجہ</td><td>کامیابی کی ترغیب</td><td>اعلیٰ درجے کے وسائل، لنگر پوائنٹ کی اعلیٰ رسائی، تہذیب کی عزت</td><td>غیر معمولی شراکت کرنے والے سادھک</td></tr></tbody></table><p>پہلا درجہ &quot;بنیادی لکیر&quot; ہے، اس بات کو یقینی بناتا ہے کہ کوئی بھی ترک نہ ہو؛ دوسرا درجہ &quot;فرق کی تلافی&quot; ہے، ابتدائی صلاحیت کے فرق کی تلافی کرتا ہے؛ تیسرا درجہ &quot;باصلاح افراد کی ترقی&quot; ہے، صلاحیت رکھنے والے افراد کو مزید مواقع دیتا ہے؛ چوتھا درجہ &quot;ترغیب&quot; ہے، غیر معمولی شراکت کاروں کو انعام دیتا ہے۔ چاروں درجے مرحلہ وار آگے بڑھتے ہیں، اور ایک مکمل ضمانت اور ترغیب کا نظام بناتے ہیں۔</p><h2 id="رابعًا-بنیادی-ضمانت-کا-مخصوص-مواد" tabindex="-1">رابعًا. بنیادی ضمانت کا مخصوص مواد <a class="header-anchor" href="#رابعًا-بنیادی-ضمانت-کا-مخصوص-مواد" aria-label="Permalink to &quot;رابعًا. بنیادی ضمانت کا مخصوص مواد&quot;">​</a></h2><p>بنیادی ضمانت سب کے لیے راستے کے نظام کا بنیادی حصہ ہے، اور اس میں خاص طور پر درج ذیل مواد شامل ہیں:</p><h3 id="_4-1-سادھائی-کے-طریقے-کی-ضمانت" tabindex="-1">4.1 سادھائی کے طریقے کی ضمانت <a class="header-anchor" href="#_4-1-سادھائی-کے-طریقے-کی-ضمانت" aria-label="Permalink to &quot;4.1 سادھائی کے طریقے کی ضمانت&quot;">​</a></h3><p>تین سو اصلی سادھائی کے نظام کے بنیادی طریقے تمام زندگیوں کے لیے مفت کھلے ہیں، کوئی داخلے کی رکاوٹ نہیں ہے۔ ہر زندگی آزادانہ طور پر اپنے لیے موزوں سادھائی کا نظام منتخب کر سکتی ہے، کسی فیس کی ادائیگی کی ضرورت نہیں، کسی مخصوص فرقے میں شامل ہونے کی ضرورت نہیں، کسی اہلیت کی جانچ سے گزرنے کی ضرورت نہیں۔ لنگر پوائنٹ جال نظام کی مطابقت کی تشخیص فراہم کرتا ہے، سادھک کی مدد کرتا ہے کہ وہ اپنے لیے سب سے موزوں راستہ تلاش کرے۔</p><h3 id="_4-2-سادھائی-کے-وسائل-کی-ضمانت" tabindex="-1">4.2 سادھائی کے وسائل کی ضمانت <a class="header-anchor" href="#_4-2-سادھائی-کے-وسائل-کی-ضمانت" aria-label="Permalink to &quot;4.2 سادھائی کے وسائل کی ضمانت&quot;">​</a></h3><p>پیداوار سے منسلک معاہدے کے طریقہ کار اور عوامی وسائل کی تقسیم کے ذریعے، اس بات کو یقینی بنایا جاتا ہے کہ ہر زندگی کو بنیادی سادہائی کو برقرار رکھنے کے لیے درکار وسائل مل جائیں۔ بنیادی وسائل کی تقسیم میں شامل ہیں: کم از کم مقدار میں توانائی کی فراہمی، بنیادی سادھائی کی دوائیں، عام سادھائی کے آلات کے استعمال کا حق۔ وسائل کی کمی والے جہتوں کے لیے، لنگر پوائنٹ جال کے ذریعے جہت کی وسائل کی تقسیم کی جاتی ہے۔</p><h3 id="_4-3-سادھائی-کے-ماحول-کی-ضمانت" tabindex="-1">4.3 سادھائی کے ماحول کی ضمانت <a class="header-anchor" href="#_4-3-سادھائی-کے-ماحول-کی-ضمانت" aria-label="Permalink to &quot;4.3 سادھائی کے ماحول کی ضمانت&quot;">​</a></h3><p>سمبیوٹک تہذیب نے ہر سیارے اور جہت میں عوامی سادھائی کی جگہیں بنائی ہیں، جن میں عوامی سادھائی کے کمرے، توانائی کے ارتکاز کے ضابطے کے علاقے، قانون کے ادراک کے کمرے وغیرہ شامل ہیں۔ یہ جگہیں تمام زندگیوں کے لیے مفت یا کم قیمت پر کھلی ہیں، اس بات کو یقینی بناتی ہیں کہ یہاں تک کہ سب سے غریب سادھک کے پاس بھی موزوں سادھائی کا ماحول ہے۔</p><h3 id="_4-4-اساتذہ-کی-رہنمائی-کی-ضمانت" tabindex="-1">4.4 اساتذہ کی رہنمائی کی ضمانت <a class="header-anchor" href="#_4-4-اساتذہ-کی-رہنمائی-کی-ضمانت" aria-label="Permalink to &quot;4.4 اساتذہ کی رہنمائی کی ضمانت&quot;">​</a></h3><p>نسل در نسل اساتذہ کا جال قائم کیا گیا ہے، اور اعلیٰ درجے کے سادھکوں پر ابتدائی درجے کے سادھکوں کو بنیادی رہنمائی فراہم کرنے کی ذمہ داری ہے۔ ہر ابتدائی درجے کا سادھک لنگر پوائنٹ جال کے ذریعے استاد کی ملازمت کے لیے درخواست دے سکتا ہے، اور مفت بنیادی سوالات کے جوابات اور سادھائی کے مشورے حاصل کر سکتا ہے۔ خصوصی مشکلات والے سادھکوں کے لیے، ایک سے ایک ہدایت شدہ رہنمائی فراہم کی جاتی ہے۔</p><h3 id="_4-5-طبی-بحالی-کی-ضمانت" tabindex="-1">4.5 طبی بحالی کی ضمانت <a class="header-anchor" href="#_4-5-طبی-بحالی-کی-ضمانت" aria-label="Permalink to &quot;4.5 طبی بحالی کی ضمانت&quot;">​</a></h3><p>سمبیوٹک طبی نظام سادھکوں کو مفت بنیادی طبی اور سادھائی کی خرابی کی بحالی کی خدمات فراہم کرتا ہے۔ سادھائی کے عمل میں چوٹ، سادھائی کی خرابی، توانائی کی خرابی وغیرہ کی صورت میں، بروقت علاج اور بحالی کی مدد حاصل کی جا سکتی ہے، اس بات کو یقینی بناتے ہوئے کہ سادھک حادثے کی وجہ سے ارتقاء کی صلاحیت سے محروم نہ ہو۔</p><h2 id="خامسًا-ہدایت-شدہ-مدد-کے-اہداف-اور-طریقے" tabindex="-1">خامسًا. ہدایت شدہ مدد کے اہداف اور طریقے <a class="header-anchor" href="#خامسًا-ہدایت-شدہ-مدد-کے-اہداف-اور-طریقے" aria-label="Permalink to &quot;خامسًا. ہدایت شدہ مدد کے اہداف اور طریقے&quot;">​</a></h2><p>ہدایت شدہ مدد درج ذیل کمزور گروہوں کے لیے ہے:</p><ul><li><strong>کم صلاحیت والے افراد</strong>: پیدائشی قابلیت کم، سادھائی کی پیش رفت سست ایسے افراد، جو اضافی وسائل کی تقسیم اور ذاتی نوعیت کی رہنمائی حاصل کرتے ہیں</li><li><strong>غریب نسلیں</strong>: مجموعی طور پر وسائل کی کمی، ارتقاء کی سطح کم ایسی نسلیں، جو نسلی ترقی کے فنڈ سے ہدایت شدہ مدد حاصل کرتی ہیں</li><li><strong>تباہی کے بعد کے گروہ</strong>: جہت کی تباہی، جنگ وغیرہ کی وجہ سے گھر اور وسائل کھو چکے گروہ، جو ہنگامی امداد اور تعمیر نو کی مدد حاصل کرتے ہیں</li><li><strong>معذور سادھک</strong>: مختلف وجوہات کی بنا پر جسمانی یا ذہنی معذوری والے سادھک، جو خصوصی سادھائی کے معاون آلات اور اپنی مرضی کے مطابق سادھائی کے منصوبے حاصل کرتے ہیں</li><li><strong>غیر معمولی زندگی</strong>: عام سادھائی کے نظام کے مطابق نہ ہونے والی غیر معمولی زندگی، جو خصوصی تشخیص اور اپنی مرضی کے مطابق ارتقاء کے راستے حاصل کرتی ہیں</li></ul><p>ہدایت شدہ مدد کے طریقے میں شامل ہیں: اضافی وسائل کی تقسیم، ایک سے ایک استاد کی رہنمائی، اپنی مرضی کے مطابق سادھائی کے منصوبے، خصوصی آلات کی فراہمی، جہت کی تبادلے کے مواقع وغیرہ۔ مدد کا مقصد کمزور گروہوں کو بنیادی ارتقاء کی سطح تک پہنچانے میں مدد کرنا ہے، اور پھر بتدریج عام زیادہ محنت زیادہ انعام کے تقسیمی نظام میں منتقل کرنا ہے۔</p><h2 id="سادسًا-ضمانت-کے-نظام-کے-فنڈز-اور-وسائل-کے-ذرائع" tabindex="-1">سادسًا. ضمانت کے نظام کے فنڈز اور وسائل کے ذرائع <a class="header-anchor" href="#سادسًا-ضمانت-کے-نظام-کے-فنڈز-اور-وسائل-کے-ذرائع" aria-label="Permalink to &quot;سادسًا. ضمانت کے نظام کے فنڈز اور وسائل کے ذرائع&quot;">​</a></h2><p>سب کے لیے راستے کی ضمانت کے نظام کے چلانے کے لیے بہت سارے وسائل اور فنڈز درکار ہیں، اور ان کے ذرائع میں شامل ہیں:</p><ol><li><strong>عوامی وسائل کی آمدنی</strong>: سمبیوٹک تہذیب کے ذریعے براہ راست چلائے جانے والے عوامی روحانی رگ، توانائی کی کان کی رگ، دواؤں کے کھیت وغیرہ وسائل کی پیداوار</li><li><strong>شراکت کے ریگولیٹری ٹیکس</strong>: اعلیٰ شراکت کاروں سے ایک مخصوص تناسب کا &quot;شراکت کا ریگولیٹری ٹیکس&quot; وصول کرنا، جو ضمانت کے نظام کے چلانے کے لیے استعمال ہوتا ہے (شرح بڑھتی ہوئی، زیادہ سے زیادہ 30% سے زیادہ نہیں)</li><li><strong>تہذیب کی ترقی کا فنڈ</strong>: لنگر پوائنٹ جال کے چلانے سے پیدا ہونے والی اضافی توانائی، جس کا کچھ حصہ تہذیب کی ترقی کے فنڈ میں داخل ہوتا ہے</li><li><strong>ٹیکنالوجی لائسنس کی آمدنی</strong>: سمبیوٹک تہذیب کی ملکیت والی قانون کی انجینئرنگ ٹیکنالوجی کے لائسنس کے استعمال کی فیس</li><li><strong>عطیات اور وراثت</strong>: افراد اور نسلوں کی رضاکارانہ عطیات</li></ol><p>ضمانت کے نظام کی آمدنی اور خرچہ دس ہزار نسلوں کی جمہوری پارلیمنٹ کے ماتحت ضمانت کمیٹی کے ذریعے چلائی جاتی ہے، اور اکاؤنٹس باقاعدگی سے تمام زندگیوں کے سامنے شائع کیے جاتے ہیں اور نگرانی کی جاتی ہے۔</p><h2 id="اختتام" tabindex="-1">اختتام <a class="header-anchor" href="#اختتام" aria-label="Permalink to &quot;اختتام&quot;">​</a></h2><p>سب کے لیے راستے کی ضمانت کا نظام لنگر سمبیوٹک تہذیب کی سماجی انصاف کی بنیادی سنگ ہے۔ یہ اس بات کو یقینی بناتا ہے کہ سادھائی اور ارتقاء پر مرکوز تہذیب میں، کوئی بھی زندگی نسب، صلاحیت یا غربت کی وجہ سے ارتقاء کے نظام کے ذریعے ترک نہ ہو۔ سب کے لیے راستہ کا مطلب یکساںیت کرنا نہیں ہے، بلکہ ہر زندگی کو ایک منصفانہ نقطہ آغاز، ایک اوپر جانے والا چینل، اور ایک ترک نہ کیے جانے کا وعدہ دینا ہے۔ سب کے لیے راستے کی ضمانت میں، ہر زندگی اپنے ارتقاء کا راستہ تلاش کر سکتی ہے۔</p><h2 id="متعلقہ-دستاویزات" tabindex="-1">متعلقہ دستاویزات <a class="header-anchor" href="#متعلقہ-دستاویزات" aria-label="Permalink to &quot;متعلقہ دستاویزات&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (زیادہ محنت زیادہ انعام کی تقسیم کا اصول)</li><li>07-自生自长进化法则 (خود پیدا خود بڑھنے والے ارتقاء کا قانون)</li><li>38-共生医疗体系 (سمبیوٹک طبی نظام)</li></ul>',43)])])}const c=a(d,[["render",l]]);export{p as __pageData,c as default};
